How does this singleton pattern work?
```javascript
const Singleton = (() => {
  let instance;
  return {
    getInstance() {
      if (!instance) {
        instance = { data: 'unique' };
      }
      return instance;
    }
  };
})();
const s1 = Singleton.getInstance();
const s2 = Singleton.getInstance();
console.log(s1 === s2);
```
